func exist(_ board: [[Character]], _ word: String) -> Bool {
    var g = board
    let w = Array(word), rows = g.count, cols = g[0].count
    func dfs(_ r: Int, _ c: Int, _ i: Int) -> Bool {
        if i == w.count { return true }
        guard r >= 0, r < rows, c >= 0, c < cols, g[r][c] == w[i] else { return false }
        g[r][c] = "#"
        defer { g[r][c] = w[i] }
        return dfs(r + 1, c, i + 1) || dfs(r - 1, c, i + 1) || dfs(r, c + 1, i + 1) || dfs(r, c - 1, i + 1)
    }
    for r in 0..<rows { for c in 0..<cols where dfs(r, c, 0) { return true } }
    return false
}
